(async function() {
  var s = window.OfficeV2.getState();
  var bridgeInst = s.instances['test-bold-1'];
  var editor = bridgeInst.editor;
  var pos = null;
  editor.state.doc.descendants(function(node, nodePos) {
    if (pos !== null) return false;
    if (node.isText && node.marks && node.marks.some(function(m) { return m.type.name === 'bold'; })) {
      pos = { from: nodePos, to: nodePos + node.nodeSize };
      return false;
    }
  });
  if (!pos) return { err: 'no bold node found' };
  editor.commands.setTextSelection(pos);
  await new Promise(function(r) { setTimeout(r, 200); });
  var beforeIsBold = editor.isActive('bold');
  var selFrom = editor.state.selection.from;
  var selTo = editor.state.selection.to;
  var selEmpty = editor.state.selection.empty;
  var chainResult = editor.chain().focus().toggleBold().run();
  await new Promise(function(r) { setTimeout(r, 300); });
  var afterIsBold = editor.isActive('bold');
  var stillHasBold = false;
  editor.state.doc.descendants(function(node) {
    if (node.isText && node.marks && node.marks.some(function(m) { return m.type.name === 'bold'; })) {
      stillHasBold = true;
    }
  });
  return { foundPos: pos, selFrom: selFrom, selTo: selTo, selEmpty: selEmpty, beforeIsBold: beforeIsBold, chainResult: chainResult, afterIsBold: afterIsBold, stillHasBold: stillHasBold };
})()
